arguments.command:
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100Pays95()
    {
        var checkout = new CheckoutPricing.Application.Checkout();

        var total = checkout.CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Passed" | head

